   624	// ServeHTTP implements `http.Handler` interface, which serves HTTP requests.
   625	func (e *Echo) ServeHTTP(w http.ResponseWriter, r *http.Request) {
   626		// Acquire context
   627		c := e.pool.Get().(*context)
   628		c.Reset(r, w)
   629		h := NotFoundHandler
   630	
   631		if e.premiddleware == nil {
   632			e.findRouter(r.Host).Find(r.Method, GetPath(r), c)
   633			h = c.Handler()
   634			h = applyMiddleware(h, e.middleware...)
   635		} else {
   636			h = func(c Context) error {
   637				e.findRouter(r.Host).Find(r.Method, GetPath(r), c)
   638				h := c.Handler()
   639				h = applyMiddleware(h, e.middleware...)
   640				return h(c)
   641			}
   642			h = applyMiddleware(h, e.premiddleware...)
   643		}
   644	
   645		// Execute chain
   646		if err := h(c); err != nil {
   647			e.HTTPErrorHandler(err, c)
   648		}
   649	
   650		// Release context
   651		e.pool.Put(c)
   652	}
