			isTLS:    true,
			expected: "https",
		},
		{
			name:     "X-Forwarded-Proto https",
			headers:  map[string]string{echo.HeaderXForwardedProto: "https"},
			expected: "https",
		},
		{
			name:     "X-Forwarded-Protocol http",
			headers:  map[string]string{echo.HeaderXForwardedProtocol: "http"},
			expected: "http",
		},
		{
			name: "ignores invalid X-Forwarded-Proto and uses X-Forwarded-Protocol",
			headers: map[string]string{
				echo.HeaderXForwardedProto:    "garbage",
				echo.HeaderXForwardedProtocol: "https",
			},
			expected: "https",
		},
		{
			name: "ignores invalid forwarded headers and falls back to http",
			headers: map[string]string{
				echo.HeaderXForwardedProto:    "garbage",
				echo.HeaderXForwardedProtocol: "garbage",
			},
			expected: "http",
		},
		{
			name:     "X-Forwarded-Ssl on",
			headers:  map[string]string{echo.HeaderXForwardedSsl: "on"},
			expected: "https",
		},
		{
			name:     "X-Forwarded-Ssl off",
			headers:  map[string]string{echo.HeaderXForwardedSsl: "off"},
			expected: "http",
		},
		{
			name:     "X-Url-Scheme https",
			headers:  map[string]string{echo.HeaderXUrlScheme: "https"},
			expected: "https",
		},
	}

	for _, tc := range testCases {
		tc := tc
		t.Run(tc.name, func(t *testing.T) {
			e := echo.New()
			req := httptest.NewRequest(http.MethodGet, "/", nil)
			rec := httptest.NewRecorder()
			if tc.isTLS {
				req.TLS = &tls.ConnectionState{}
			}
			for k, v := range tc.headers {
				req.Header.Set(k, v)
			}
			c := e.NewContext(req, rec)
			if got := c.Scheme(); got != tc.expected {
				t.Errorf("Scheme() = %q, want %q", got, tc.expected)
			}
		})
	}
}
