		"root":      {"GET /"},
		"any":       {"GET /*"},
		"anyroot":   {"GET /", "GET /*"},
		"param":     {"GET /:id"},
		"paramany":  {"GET /:id", "GET /*"},
		"static":    {"GET /a/b"},
		"mixed":     {"GET /", "GET /a/:b", "GET /a/*", "POST /x"},
	}
	paths := []string{"", "*", "//", "http://host/path", "a", "?", "#"}
	for rsName, rs := range routeSets {
		for _, p := range paths {
			func() {
				defer func() {
					if r := recover(); r != nil {
						t.Errorf("PANIC routeSet=%s path=%q: %v", rsName, p, r)
					}
				}()
				e := New()
				for _, rt := range rs {
					var m, pa string
					fmt.Sscanf(rt, "%s %s", &m, &pa)
					e.Add(m, pa, func(c Context) error { return c.String(http.StatusOK, "ok") })
				}
				req := httptest.NewRequest(http.MethodGet, "/", nil)
				req.URL.Path = p
				req.URL.RawPath = ""
				rec := httptest.NewRecorder()
				e.ServeHTTP(rec, req)
				t.Logf("routeSet=%s path=%q -> %d", rsName, p, rec.Code)
			}()
		}
	}
}
