func mw(marker string) MiddlewareFunc {
	return func(next HandlerFunc) HandlerFunc {
		return func(c Context) error {
			c.Response().Header().Add("X-MW", marker)
			return next(c)
		}
	}
}

func hit(t *testing.T, e *Echo, method, path string) (int, string, []string) {
	req := httptest.NewRequest(method, path, nil)
	rec := httptest.NewRecorder()
	e.ServeHTTP(rec, req)
	return rec.Code, rec.Body.String(), rec.Header().Values("X-MW")
}

func h(body string) HandlerFunc { return func(c Context) error { return c.String(200, body) } }

func check(t *testing.T, name string, e *Echo, method, path, wantBody string, wantMW []string) {
	code, body, got := hit(t, e, method, path)
	ok := body == wantBody && strings.Join(got, ",") == strings.Join(wantMW, ",")
	t.Logf("%-4s %s %s -> %d body=%q mw=%v (want %q %v) ok=%v", name, method, path, code, body, got, wantBody, wantMW, ok)
	if !ok {
		t.Errorf("%s: %s %s got body=%q mw=%v want body=%q mw=%v", name, method, path, body, got, wantBody, wantMW)
	}
}

