		name    string
		handler echo.HandlerFunc
	}{
		{"NoContent", func(c echo.Context) error { return c.NoContent(http.StatusOK) }},
		{"EmptyString", func(c echo.Context) error { return c.String(http.StatusOK, "") }},
	}
